import"./base_page.js";import{PolymerElement}from"//resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{I18nMixin}from"chrome://resources/ash/common/cr_elements/i18n_mixin.js";import{getTemplate}from"./final_page.html.js";const FinalPageElementBase=I18nMixin(PolymerElement);export class FinalPageElement extends FinalPageElementBase{static get is(){return"final-page"}static get template(){return getTemplate()}static get properties(){return{delegate:Object,showError:Boolean,message:String,errorMessage:String}}getTitle_(showError){if(this.delegate.shouldShowPageTitle()){return showError?this.i18n("finalPageErrorTitle"):this.i18n("finalPageTitle")}return null}getMessage_(showError){return showError?this.errorMessage:this.message}getPageBodyClass_(showError){return showError?"error":""}getJellyIllustrationName_(showError){return showError?"cellular-setup-illo:error":"cellular-setup-illo:final-page-success"}}customElements.define(FinalPageElement.is,FinalPageElement);